// Demo input: pin the sample array from ../demo-data/open-estimates.json
const input = Array.isArray($json) ? $json : [$json];
const lostReasonEnum = ['price', 'timing', 'competitor', 'no-response', 'scope'];
return input.map((estimate) => {
  const quoteAgeDays = Number(estimate.quoteAgeDays ?? 0);
  const estimateValue = Number(estimate.estimateValue ?? 0);
  const status = `${estimate.status ?? 'open'}`.toLowerCase();
  const rawLostReason = `${estimate.lostReason ?? ''}`.toLowerCase();
  const lostReason = lostReasonEnum.includes(rawLostReason) ? rawLostReason : null;
  let cadenceStep;
  if (status === 'lost') cadenceStep = 'tag-lost-reason';
  else if (quoteAgeDays >= 14) cadenceStep = 'final-touch-d14';
  else if (quoteAgeDays >= 7) cadenceStep = 'sms-touch-d7';
  else if (quoteAgeDays >= 3) cadenceStep = 'email-touch-d3';
  else cadenceStep = 'wait';
  const financeReminderEligible = estimateValue >= 7500;
  let nextAction;
  if (cadenceStep === 'wait') nextAction = 'No message today.';
  else if (cadenceStep === 'tag-lost-reason') nextAction = `Write lostReason (${lostReason ?? 'unset'}) to HubSpot; no further messages.`;
  else if (financeReminderEligible) nextAction = 'Send approved follow-up touch with contractor-approved financing reminder copy.';
  else nextAction = 'Send approved follow-up touch.';
  return { json: { ...estimate, quoteAgeDays, estimateValue, cadenceStep, lostReason, financeReminderEligible, nextAction } };
});
